@SuppressWarnings("unchecked")
@Test
public void leftOuterJoin() {
    JavaPairRDD<Integer, Integer> rdd1 = sc.parallelizePairs(Arrays.asList(new Tuple2<>(1, 1), new Tuple2<>(1, 2), new Tuple2<>(2, 1), new Tuple2<>(3, 1)));
    JavaPairRDD<Integer, Character> rdd2 = sc.parallelizePairs(Arrays.asList(new Tuple2<>(1, 'x'), new Tuple2<>(2, 'y'), new Tuple2<>(2, 'z'), new Tuple2<>(4, 'w')));
    List<Tuple2<Integer, Tuple2<Integer, Optional<Character>>>> joined = rdd1.leftOuterJoin(rdd2).collect();
    Assert.assertEquals(5, joined.size());
    Tuple2<Integer, Tuple2<Integer, Optional<Character>>> firstUnmatched = rdd1.leftOuterJoin(rdd2).filter(new Function<Tuple2<Integer, Tuple2<Integer, Optional<Character>>>, Boolean>() {

        @Override
        public Boolean call(Tuple2<Integer, Tuple2<Integer, Optional<Character>>> tup) {
            return !tup._2()._2().isPresent();
        }
    }).first();
    Assert.assertEquals(3, firstUnmatched._1().intValue());
}

@Test
public void foldReduce() {
    JavaRDD<Integer> rdd = sc.parallelize(Arrays.asList(1, 1, 2, 3, 5, 8, 13));
    Function2<Integer, Integer, Integer> add = new Function2<Integer, Integer, Integer>() {

        @Override
        public Integer call(Integer a, Integer b) {
            return a + b;
        }
    };
    int sum = rdd.fold(0, add);
    Assert.assertEquals(33, sum);
    sum = rdd.reduce(add);
    Assert.assertEquals(33, sum);
}

@Test
public void treeReduce() {
    JavaRDD<Integer> rdd = sc.parallelize(Arrays.asList(-5, -4, -3, -2, -1, 1, 2, 3, 4), 10);
    Function2<Integer, Integer, Integer> add = new Function2<Integer, Integer, Integer>() {

        @Override
        public Integer call(Integer a, Integer b) {
            return a + b;
        }
    };
    for (int depth = 1; depth <= 10; depth++) {
        int sum = rdd.treeReduce(add, depth);
        Assert.assertEquals(-5, sum);
    }
}

