@Test
public void testKafkaStream() throws InterruptedException {
    final String topic1 = "topic1";
    final String topic2 = "topic2";
    // hold a reference to the current offset ranges, so it can be used downstream
    final AtomicReference<OffsetRange[]> offsetRanges = new AtomicReference<>();
    String[] topic1data = createTopicAndSendData(topic1);
    String[] topic2data = createTopicAndSendData(topic2);
    Set<String> sent = new HashSet<>();
    sent.addAll(Arrays.asList(topic1data));
    sent.addAll(Arrays.asList(topic2data));
    Map<String, String> kafkaParams = new HashMap<>();
    kafkaParams.put("metadata.broker.list", kafkaTestUtils.brokerAddress());
    kafkaParams.put("auto.offset.reset", "smallest");
    JavaDStream<String> stream1 = KafkaUtils.createDirectStream(ssc, String.class, String.class, StringDecoder.class, StringDecoder.class, kafkaParams, topicToSet(topic1)).transformToPair(// Make sure you can get offset ranges from the rdd
    new Function<JavaPairRDD<String, String>, JavaPairRDD<String, String>>() {

        @Override
        public JavaPairRDD<String, String> call(JavaPairRDD<String, String> rdd) {
            OffsetRange[] offsets = ((HasOffsetRanges) rdd.rdd()).offsetRanges();
            offsetRanges.set(offsets);
            Assert.assertEquals(topic1, offsets[0].topic());
            return rdd;
        }
    }).map(new Function<Tuple2<String, String>, String>() {

        @Override
        public String call(Tuple2<String, String> kv) {
            return kv._2();
        }
    });
    JavaDStream<String> stream2 = KafkaUtils.createDirectStream(ssc, String.class, String.class, StringDecoder.class, StringDecoder.class, String.class, kafkaParams, topicOffsetToMap(topic2, 0L), new Function<MessageAndMetadata<String, String>, String>() {

        @Override
        public String call(MessageAndMetadata<String, String> msgAndMd) {
            return msgAndMd.message();
        }
    });
    JavaDStream<String> unifiedStream = stream1.union(stream2);
    final Set<String> result = Collections.synchronizedSet(new HashSet<String>());
    unifiedStream.foreachRDD(new Function<JavaRDD<String>, Void>() {

        @Override
        public Void call(JavaRDD<String> rdd) {
            result.addAll(rdd.collect());
            for (OffsetRange o : offsetRanges.get()) {
                System.out.println(o.topic() + " " + o.partition() + " " + o.fromOffset() + " " + o.untilOffset());
            }
            return null;
        }
    });
    ssc.start();
    long startTime = System.currentTimeMillis();
    boolean matches = false;
    while (!matches && System.currentTimeMillis() - startTime < 20000) {
        matches = sent.size() == result.size();
        Thread.sleep(50);
    }
    Assert.assertEquals(sent, result);
    ssc.stop();
}

