public void testTransformWith() {
    List<List<Tuple2<String, String>>> stringStringKVStream1 = Arrays.asList(Arrays.asList(new Tuple2<>("california", "dodgers"), new Tuple2<>("new york", "yankees")), Arrays.asList(new Tuple2<>("california", "sharks"), new Tuple2<>("new york", "rangers")));
