    List<HashSet<Tuple2<String, Tuple2<String, String>>>> expected = Arrays.asList(Sets.newHashSet(new Tuple2<>("california", new Tuple2<>("dodgers", "giants")), new Tuple2<>("new york", new Tuple2<>("yankees", "mets"))), Sets.newHashSet(new Tuple2<>("california", new Tuple2<>("sharks", "ducks")), new Tuple2<>("new york", new Tuple2<>("rangers", "islanders"))));
