    List<JavaDStream<?>> listOfDStreams1 = Arrays.<JavaDStream<?>>asList(stream1, stream2);
    // This is just to test whether this transform to JavaStream compiles
    ssc.transform(listOfDStreams1, new Function2<List<JavaRDD<?>>, Time, JavaRDD<Long>>() {

        @Override
        public JavaRDD<Long> call(List<JavaRDD<?>> listOfRDDs, Time time) {
            Assert.assertEquals(2, listOfRDDs.size());
            return null;
        }
    });
    List<JavaDStream<?>> listOfDStreams2 = Arrays.<JavaDStream<?>>asList(stream1, stream2, pairStream1.toJavaDStream());
    JavaPairDStream<Integer, Tuple2<Integer, String>> transformed2 = ssc.transformToPair(listOfDStreams2, new Function2<List<JavaRDD<?>>, Time, JavaPairRDD<Integer, Tuple2<Integer, String>>>() {

        @Override
        public JavaPairRDD<Integer, Tuple2<Integer, String>> call(List<JavaRDD<?>> listOfRDDs, Time time) {
            Assert.assertEquals(3, listOfRDDs.size());
